#!/bin/sh
# Writes deps/cacert from curl's extract of Mozilla's trusted roots: cacert.c
# holds cacert.pem as one C string, which the HTTP client uses where the
# system has no bundle of its own. Run it from the repository root with the
# date of a release listed on https://curl.se/docs/caextract.html, then pin
# and publish deps/cacert as the README's Building section describes:
#
#     tools/cacert.sh 2026-10-20
#
# It needs curl and shasum.
set -eu
date="$1"
pem="cacert-$date.pem"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

curl -fsSL -o "$work/$pem" "https://curl.se/ca/$pem"
curl -fsSL -o "$work/$pem.sha256" "https://curl.se/ca/$pem.sha256"
(cd "$work" && shasum -a 256 -c "$pem.sha256" >/dev/null)

rm -rf deps/cacert
mkdir -p deps/cacert
curl -fsSL -o deps/cacert/LICENSE https://www.mozilla.org/media/MPL/2.0/index.txt
cat > deps/cacert/cacert.h <<'EOF'
#pragma once

#include <stddef.h>

// CACERT_PEM is Mozilla's trusted roots in PEM, as curl extracts them in cacert.pem.
extern const char CACERT_PEM[];
extern const size_t CACERT_PEM_SIZE;
EOF
{
  echo "// Generated by tools/cacert.sh from https://curl.se/ca/$pem, under the MPL 2.0 in LICENSE."
  echo '#include "cacert.h"'
  echo
  echo 'const char CACERT_PEM[] ='
  sed -e 's/\\/\\\\/g' -e 's/"/\\"/g' -e 's/^/    "/' -e 's/$/\\n"/' -e '$ s/$/;/' "$work/$pem"
  echo 'const size_t CACERT_PEM_SIZE = sizeof CACERT_PEM - 1;'
} > deps/cacert/cacert.c
echo "wrote deps/cacert from $pem"
